Translate("ptBR", "hillsbrad-foothills", {
	title = "Contraforte de Eira dos Montes",
	aliases = { "Eira dos Montes" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Contraforte de Eira dos Montes é a verde marca meridional do antigo reino de {link:lordaeron}Lordaeron{/link}. Estende-se das neves das {link:alterac-mountains}Montanhas de Alterac{/link} até uma costa amena à beira-mar. A praga que matou Lordaeron passou ao largo, e por um tempo Eira dos Montes pareceu poupada. Não foi. Hoje o contraforte é um campo de batalha. Os humanos de {link:southshore}Costa Sul{/link} guardam o litoral, os {link:forsaken}Renegados{/link} dominam a {link:tarren-mill}Serraria Tarren{/link}, no norte, e entre eles as fazendas de Eira dos Montes queimam uma a uma.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra quando as primeiras aldeias surgiram nestas colinas. Fizeram parte de {link:lordaeron}Lordaeron{/link} enquanto aquele reino existiu. Na fronteira leste ergue-se a antiga muralha que leva o nome de {link:thoradin}Thoradin{/link}, o fundador de {link:arathor}Arathor{/link}. Quando {link:stormwind-city}Ventobravo{/link} caiu na {link:first-war}Primeira Guerra{/link}, seus refugiados desembarcaram em {link:southshore}Costa Sul{/link}, e Eira dos Montes foi a primeira terra do norte a recebê-los.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[Eira dos Montes está presa entre duas guerras. A {link:high-executor-darthalia}Alta Executora Darthalia{/link} comanda os {link:forsaken}Renegados{/link} da {link:tarren-mill}Serraria Tarren{/link} em nome da {link:sylvanas-windrunner}Dama Sombria{/link} e de {link:varimathras}Varimathras{/link}. Sua Guarda da Morte ataca as fazendas dos {link:hillsbrad-fields}Campos de Eira dos Montes{/link}, e os boticários da {link:royal-apothecary-society}Real Sociedade de Boticários{/link} testam seus novos venenos nos fazendeiros e em seus animais. {link:southshore}Costa Sul{/link} e os anões de {link:dun-garok}Dun Garok{/link} respondem com os poucos soldados que têm. Enquanto isso, a {link:syndicate}Camarilha{/link} ataca os dois lados a partir das ruínas do {link:durnholde-keep}Forte do Desterro{/link}. Acredita-se que seus assassinos já mataram um magistrado de Costa Sul, e eles caçam o próximo. {link:orcs}Orcs{/link} enviados pelo próprio {link:thrall}Thrall{/link} chegaram há pouco à Serraria Tarren, pois o Forte do Desterro foi outrora a prisão do Chefe Guerreiro, e ele quer algo de volta de lá.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O povo de {link:southshore}Costa Sul{/link}.{/b} Pescadores, soldados e estudiosos, leais à {link:alliance}Aliança{/link}.
• {b}Os fazendeiros de Eira dos Montes.{/b} Ainda trabalham os campos a oeste do rio, sob os olhos do inimigo.
• {b}Os {link:forsaken}Renegados{/link}.{/b} Sua Guarda da Morte, seus Sicários e seus boticários dominam a {link:tarren-mill}Serraria Tarren{/link}.
• {b}{link:orcs}Orcs{/link} da {link:horde}Horda{/link}.{/b} Um pequeno bando enviado de {link:durotar}Durotar{/link}, e um ferreiro que trabalha discretamente na Serraria Tarren.
• {b}Os anões de {link:dun-garok}Dun Garok{/link}.{/b} Uma guarnição de {link:dwarves}anões{/link} no sudeste, jurada a defender os humanos e sua mina.
• {b}A {link:syndicate}Camarilha{/link}.{/b} Ladrões e magos das sombras a serviço dos senhores caídos de {link:alterac-mountains}Alterac{/link}.
• {b}Feras e saqueadores.{/b} {link:murlocs}Murlocs{/link} na {link:western-strand}Praia Ocidental{/link}, {link:naga}nagas{/link} na {link:eastern-strand}Praia Oriental{/link}, {link:gnolls}gnolls{/link} no {link:nethander-stead}Sítio de Nethander{/link} e ogros que descem de Alterac.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Refugiados.{/b} Depois da queda de {link:stormwind-city}Ventobravo{/link}, os sobreviventes cruzaram o mar e desembarcaram em {link:southshore}Costa Sul{/link}. Dali, a notícia dos orcs foi levada ao Rei {link:terenas-menethil}Terenas Menethil{/link}.
• {b}A Segunda Guerra.{/b} {link:anduin-lothar}Anduin Lothar{/link} reuniu os exércitos da {link:alliance}Aliança{/link} em Eira dos Montes. A {link:horde}Horda{/link} desembarcou perto de Costa Sul, e aqui os dois exércitos se enfrentaram na primeira grande batalha em terra da {link:second-war}Segunda Guerra{/link}. Aqui também os cavaleiros da morte da Horda enfrentaram pela primeira vez os paladinos de {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}.
• {b}Os Campos.{/b} Depois da guerra, o {link:durnholde-keep}Forte do Desterro{/link} tornou-se a sede dos campos onde os orcs derrotados eram mantidos. Em seus salões, um jovem {link:orcs}orc{/link} chamado {link:thrall}Thrall{/link} foi criado como escravo. Ele fugiu, voltou à frente de uma nova Horda e reduziu o forte a ruínas.
• {b}Os Dias Atuais.{/b} {link:lordaeron}Lordaeron{/link} não existe mais, e até suas colinas do sul escapam das mãos humanas.]=],
		},
		{
			title = "Lendas do Contraforte",
			text = [=[• O povo de {link:southshore}Costa Sul{/link} diz que seus cozinheiros são os melhores ao norte de {link:stormwind-city}Ventobravo{/link}. Viajantes vindos de lugares tão distantes quanto {link:darkshire}Vila Sombria{/link} já vieram por uma tigela da sopa de tartaruga do Chef Jessen.
• Um feiticeiro chamado {link:helcular}Helcular{/link} jaz enterrado no cemitério de Costa Sul. Foi morto por uma multidão de moradores antes que seu ritual sombrio terminasse. Alguns na {link:tarren-mill}Serraria Tarren{/link} pretendem concluí-lo.]=],
		},
	},
})

Translate("ptBR", "southshore", {
	title = "Costa Sul",
	sections = {
		{
			title = "Resumo",
			text = [=[Costa Sul é uma cidade portuária no litoral sul de {link:hillsbrad-foothills}Eira dos Montes{/link}, construída em torno de seu porto, sua estalagem e sua prefeitura. Era uma aldeia de pescadores quando os refugiados de {link:stormwind-city}Ventobravo{/link} desembarcaram ali. Continua leal à {link:alliance}Aliança{/link}, e é agora uma das últimas cidades humanas do norte. O {link:magistrate-henry-maleb}Magistrado Henry Maleb{/link} a governa, e o {link:marshal-redpath}Marechal Redpath{/link} comanda sua guarda. A {link:syndicate}Camarilha{/link} jurou sua ruína, e os {link:forsaken}Renegados{/link} da {link:tarren-mill}Serraria Tarren{/link} dizem abertamente que Costa Sul vai queimar depois de Eira dos Montes.]=],
		},
		{
			title = "O Porto",
			text = [=[Grifos voam de sua colina. Há pouco tempo, novos navios começaram a atracar em seu píer, navegando para o {link:menethil-harbor}Porto de Menethil{/link} e para {link:auberdine}Auberdine{/link}, na distante {link:kalimdor}Kalimdor{/link}. Um emissário do {link:kirin-tor}Kirin Tor{/link} também veio se instalar na cidade.]=],
		},
	},
})

Translate("ptBR", "tarren-mill", {
	title = "Serraria Tarren",
	sections = {
		{
			title = "Resumo",
			text = [=[A Serraria Tarren era uma cidade humana de {link:lordaeron}Lordaeron{/link}, cercada de pomares nas colinas abaixo de {link:alterac-mountains}Alterac{/link}. Sua igreja e suas casas ainda estão de pé, mas seus pomares estão secos, e seu povo são os mortos. Os {link:forsaken}Renegados{/link} a mantêm como sua fortaleza no sul. Daqui a {link:high-executor-darthalia}Alta Executora Darthalia{/link} faz guerra a {link:hillsbrad-foothills}Eira dos Montes{/link}, e os boticários da {link:royal-apothecary-society}Real Sociedade de Boticários{/link} preparam suas pragas. Morcegos levam cavaleiros à {link:undercity}Cidade Baixa{/link}. Um bando de orcs enviado por {link:thrall}Thrall{/link} também mantém seu acampamento na cidade, pois as ruínas do {link:durnholde-keep}Forte do Desterro{/link} ficam logo do outro lado do rio.]=],
		},
	},
})

Translate("ptBR", "durnholde-keep", {
	title = "Forte do Desterro",
	aliases = { "Desterro" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Forte do Desterro foi outrora a fortaleza mais forte do sul de {link:lordaeron}Lordaeron{/link}. Depois da {link:second-war}Segunda Guerra{/link}, foi a sede dos campos onde os orcs derrotados eram mantidos, e o Tenente-general {link:aedelas-blackmoore}Aedelas Blackmoore{/link} o governava. Aqui o pequeno {link:thrall}Thrall{/link} foi criado como escravo. Quando voltou como Chefe Guerreiro, ele rompeu suas muralhas e sepultou seu senhor sob as pedras. A {link:syndicate}Camarilha{/link} tomou as ruínas. Seus magos das sombras trabalham ali, e seus carcereiros mantêm prisioneiros orcs nas velhas celas. Um {link:orcs}orc{/link} chamado Gorgrash fugiu deles há pouco, e espera perto das muralhas.]=],
		},
	},
})

Translate("ptBR", "hillsbrad-fields", {
	title = "Campos de Eira dos Montes",
	sections = {
		{
			title = "Resumo",
			text = [=[Os Campos de Eira dos Montes são as terras de cultivo a oeste do rio, e em seu coração fica a cidade de {link:hillsbrad-foothills}Eira dos Montes{/link}. Seu magistrado, {link:magistrate-burnside}Burnside{/link}, e seu conselho guardam a antiga carta da cidade, a Proclamação de Eira dos Montes, e seu registro de cidadãos. Sua ferraria guarda um estoque de ferro. Suas fazendas alimentam todo o contraforte. É por isso que os {link:forsaken}Renegados{/link} atacam aqui primeiro. A Guarda da Morte ataca as fazendas do norte, camponeses fogem para os pomares do sul, e a cidade espera um ataque que não tem esperança de conter.]=],
		},
	},
})

Translate("ptBR", "azurelode-mine", {
	title = "Mina Veioazul",
	sections = {
		{
			title = "Resumo",
			text = [=[A Mina Veioazul fica nas colinas ao sul de {link:hillsbrad-foothills}Eira dos Montes{/link}, acima da {link:western-strand}Praia Ocidental{/link}. Seu ferro abastece as forjas da {link:alliance}Aliança{/link}. O Capataz Bonds mantém seus mineiros trabalhando, e sentinelas vigiam sua entrada. A Aliança a protege com ferocidade. Os {link:forsaken}Renegados{/link} a desejam muito. A Dama Sombria precisa de ferro para armar seus soldados, e uma mina tomada dos humanos lhe daria isso. Os mineiros têm motivo para temer. O nome de seu capataz está na lista da Alta Executora.]=],
		},
	},
})

Translate("ptBR", "dun-garok", {
	title = "Dun Garok",
	sections = {
		{
			title = "Resumo",
			text = [=[Dun Garok é uma fortaleza anã no sudeste de {link:hillsbrad-foothills}Eira dos Montes{/link}, construída junto à {link:thoradin-s-wall}Muralha de Thoradin{/link}. Sua guarnição de montanhistas, fuzileiros e sacerdotes é liderada pelo {link:captain-ironhill}Capitão Ironhill{/link}. Os anões vieram ajudar os humanos do contraforte e montam guarda sobre suas terras. Fabricam uma cerveja preta forte, e não hesitam em tomar o equipamento de um batedor Renegado descuidado quando o encontram. A {link:tarren-mill}Serraria Tarren{/link} os conta entre seus piores inimigos. Suas ordens são claras: Dun Garok precisa cair.]=],
		},
	},
})

Translate("ptBR", "nethander-stead", {
	title = "Sítio de Nethander",
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio de Nethander é uma fazenda abandonada a leste de {link:southshore}Costa Sul{/link}, do outro lado do rio. Nenhum registro diz o que foi feito da família Nethander. Os {link:gnolls}gnolls{/link} Fuçalama vivem agora em seus campos, e cogumelos pálidos chamados Flores de Fuçalama crescem densos entre o mato. As flores fedem, e os boticários da {link:tarren-mill}Serraria Tarren{/link} as valorizam exatamente por isso. São o coração de uma das misturas mais mortais da Sociedade. O {link:apothecary-lydon}Boticário Lydon{/link} já disse que os gnolls imundos servem para alguma coisa, afinal.]=],
		},
	},
})

Translate("ptBR", "purgation-isle", {
	title = "Ilha da Purgação",
	sections = {
		{
			title = "Resumo",
			text = [=[A Ilha da Purgação é uma ilha escarpada diante da costa sudoeste de {link:hillsbrad-foothills}Eira dos Montes{/link}, coroada por uma torre em ruínas e cercada por um antigo cemitério. Seus mortos não descansam. Clérigos, monges e acólitos condenados caminham entre os túmulos ao lado de paladinos e justicares amaldiçoados e de magos contorcidos. Seu poder é grande, muito além do das feras e saqueadores do continente. Nenhuma crônica registra quem eles foram em vida, que crime ou que destino os prendeu à ilha, nem por que há tantos servos da Luz entre eles.]=],
		},
	},
})

Translate("ptBR", "darrow-hill", {
	title = "Monte das Flechas",
	sections = {
		{
			title = "Resumo",
			text = [=[O Monte das Flechas ergue-se no norte de {link:hillsbrad-foothills}Eira dos Montes{/link}, abaixo das alturas de {link:alterac-mountains}Alterac{/link}. Leões-da-montanha e cervos vagam por suas encostas, e yetis assombram as cavernas acima dele. É uma terra selvagem, e nenhuma cidade se ergue nela. Foi nestas colinas que o feiticeiro {link:helcular}Helcular{/link} manteve seu covil secreto, até que os moradores de {link:southshore}Costa Sul{/link} o encontraram. Desde então os yetis tomaram suas cavernas, e as fogueiras de seu ritual ainda ardem no escuro. O covil era secreto, e nenhum registro conta como os moradores souberam dele.]=],
		},
	},
})

Translate("ptBR", "eastern-strand", {
	title = "Praia Oriental",
	sections = {
		{
			title = "Resumo",
			text = [=[A Praia Oriental é a costa rochosa a leste de {link:southshore}Costa Sul{/link}, que desce em direção a {link:dun-garok}Dun Garok{/link}. As {link:naga}nagas{/link} Daggerspine subiram do mar para reivindicá-la. Suas sereias e espreitadoras da costa caçam ao longo da praia, e entre elas caça uma naga de raro poder chamada Lady Zephris. Os oficiais de Costa Sul temem o que as nagas querem, e notícias delas chegaram ao alto comando da {link:alliance}Aliança{/link}. Ninguém em Costa Sul sabe dizer de onde as nagas vieram.]=],
		},
	},
})

Translate("ptBR", "western-strand", {
	title = "Praia Ocidental",
	sections = {
		{
			title = "Resumo",
			text = [=[A Praia Ocidental é a longa costa a oeste de {link:southshore}Costa Sul{/link}, abaixo da {link:azurelode-mine}Mina Veioazul{/link}. Os {link:murlocs}murlocs{/link} Torn Fin construíram seus acampamentos ao longo dela, perto o bastante da cidade para preocupar sua guarda. O {link:marshal-redpath}Marechal Redpath{/link} quer que eles sejam repelidos e exige suas cabeças como prova. Seu tenente prefere beber a ir, e a tarefa costuma cair nas mãos de estranhos. O tenente não come peixe há semanas. Um murloc da tribo chamado Scargil é raramente visto, e raramente esquecido por quem o encontra.]=],
		},
	},
})

Translate("ptBR", "southpoint-tower", {
	title = "Torre do Sul",
	sections = {
		{
			title = "Resumo",
			text = [=[A Torre do Sul é uma torre de vigia em ruínas no extremo oeste de {link:hillsbrad-foothills}Eira dos Montes{/link}, na estrada para {link:silverpine-forest}Pinhaprata{/link}. Outrora guardava a entrada do contraforte. Agora esconde uma única batedora Renegada. De suas muralhas quebradas, a {link:deathstalker-lesh}Sicária Lesh{/link} vigia a cidade de Eira dos Montes e envia notícias para o leste, à {link:tarren-mill}Serraria Tarren{/link}. Ela está sozinha, longe de qualquer ajuda, com as estradas da {link:alliance}Aliança{/link} por todos os lados. Sua última mensagem foi curta. Dizia que a hora de atacar havia chegado.]=],
		},
	},
})

Translate("ptBR", "thoradin-s-wall", {
	title = "Muralha de Thoradin",
	sections = {
		{
			title = "Resumo",
			text = [=[A Muralha de Thoradin é uma grande muralha partida que separa o {link:hillsbrad-foothills}Contraforte de Eira dos Montes{/link} do {link:arathi-highlands}Planalto Arathi{/link}. Leva o nome de {link:thoradin}Thoradin{/link}, o primeiro rei de {link:arathor}Arathor{/link}, e é mais antiga que qualquer reino que existe hoje. A maioria diz que foi erguida para conter os trolls Amani. Suas pedras estão rachadas e suas torres se foram, mas ela ainda marca a fronteira. Os anões de {link:dun-garok}Dun Garok{/link} construíram sua fortaleza à sua sombra. Viajantes rumo ao Planalto Arathi ainda precisam atravessá-la.]=],
		},
	},
})

Translate("ptBR", "aedelas-blackmoore", {
	title = "Aedelas Blackmoore",
	subtitle = "Senhor do Forte do Desterro",
	allegiance = "Reino de Lordaeron · Forte do Desterro",
	aliases = { "Blackmoore" },
	sections = {
		{
			title = "Resumo",
			text = [=[Aedelas Blackmoore foi o senhor do {link:durnholde-keep}Forte do Desterro{/link} e o mestre dos campos onde os orcs derrotados eram mantidos depois da {link:second-war}Segunda Guerra{/link}. Era um guerreiro duro, um bebedor inveterado e um homem de grande ambição. Encontrou um bebê {link:orcs}orc{/link} órfão na natureza e o criou como escravo. Esse orc era {link:thrall}Thrall{/link}. Blackmoore pretendia fazer dele uma arma. Em vez disso, Thrall tornou-se o Chefe Guerreiro que libertou os orcs e o matou.]=],
		},
		{
			title = "Importância",
			text = [=[Blackmoore é o homem que fez {link:thrall}Thrall{/link}, em todos os sentidos que ele não pretendia. Sua crueldade ensinou ao jovem {link:orcs}orc{/link} o que os humanos podiam ser. A bondade de outros em sua própria casa ensinou a Thrall que eles podiam ser outra coisa. Sem Blackmoore não haveria Thrall, e sem Thrall não haveria nova {link:horde}Horda{/link}.]=],
		},
		{
			title = "O Filho de um Traidor",
			text = [=[Blackmoore lutou bem na {link:second-war}Segunda Guerra{/link} e era conhecido por sua fúria contra os orcs. Mas carregava um nome pesado. Seu pai fora condenado por traição, e os sussurros seguiram o filho a vida inteira. Ele bebia para enfrentar a batalha, e bebia mais quando a guerra acabou. Quando lhe deram o {link:durnholde-keep}Desterro{/link} e os campos, seu poder cresceu, e seus vícios também.]=],
		},
		{
			title = "O Menino Orc",
			text = [=[Enquanto caçava com seu servo Tammis Foxton, Blackmoore encontrou um bebê {link:orcs}orc{/link} entre os corpos de seus pais assassinados. Levou a criança ao {link:durnholde-keep}Desterro{/link} e a chamou de {link:thrall}Thrall{/link}. Mandou ensinar o menino a ler, a escrever e a lutar, e o enviou à arena contra os campeões de outros senhores. Em segredo, sonhava com mais. Um dia Thrall lideraria um exército de orcs dos campos, e por meio dele Blackmoore governaria. Muitas vezes foi cruel com o menino, às vezes gentil, e nunca viu a diferença como Thrall a via.]=],
		},
		{
			title = "A Queda do Desterro",
			text = [=[{link:thrall}Thrall{/link} fugiu com a ajuda da filha de Tammis, {link:taretha-foxton}Taretha Foxton{/link}, a quem Blackmoore fizera sua amante contra a vontade dela. Anos depois, o {link:orcs}orc{/link} voltou à frente de uma {link:horde}Horda{/link} livre e rompeu os campos um após o outro. Na noite anterior ao cerco, Blackmoore soube que Taretha se encontrara com Thrall em segredo. Mandou executá-la. Quando Thrall veio negociar diante dos portões, um Blackmoore embriagado atirou a cabeça dela do alto das muralhas. Os orcs invadiram o forte. Thrall encontrou Blackmoore lá dentro e o matou em combate singular. Então invocou o espírito da terra, e o {link:durnholde-keep}Desterro{/link} desabou sobre o corpo de seu senhor.]=],
		},
	},
	chapters = {
		{
			title = "O Legado de Blackmoore",
			hint = "Descubra o que o senhor da Camarilha planeja para os orcs.",
			text = [=[As ambições de Blackmoore não morreram com ele. O {link:orcs}orc{/link} {link:gol-dir}Gol'dir{/link}, prisioneiro da {link:syndicate}Camarilha{/link}, soube que o senhor dela, {link:lord-aliden-perenolde}Aliden Perenolde{/link}, chamava Blackmoore de mentor. Perenolde pretendia tomar como escravos os orcs que se opunham a ele, como seu pai e seu mestre haviam planejado antes dele.]=],
		},
	},
	mentions = {
		{ text = "O Legado de Blackmoore" },
		{ text = "{link:lord-aliden-perenolde}Lorde Aliden Perenolde{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu escravo, e seu assassino" },
		{ id = "taretha-foxton", name = "Taretha Foxton", note = "sua amante, assassinada por sua ordem" },
		{ id = "aliden-perenolde", name = "Aliden Perenolde", note = "seu discípulo" },
		{ id = "durnholde-keep", name = "Forte do Desterro", note = "sua fortaleza e seu túmulo" },
	},
})

Translate("ptBR", "taretha-foxton", {
	title = "Taretha Foxton",
	subtitle = "Amiga de Thrall",
	allegiance = "Forte do Desterro",
	aliases = { "Taretha", "Tari" },
	sections = {
		{
			title = "Resumo",
			text = [=[Taretha Foxton era uma menina do {link:durnholde-keep}Forte do Desterro{/link}, filha de Tammis Foxton, servo de {link:aedelas-blackmoore}Blackmoore{/link}. Foi o que o jovem {link:thrall}Thrall{/link} conheceu de mais próximo de uma família. Escreveu-lhe em segredo quando ele era escravo, ajudou-o a fugir e pagou a liberdade dele com a própria vida.]=],
		},
		{
			title = "Importância",
			text = [=[Com {link:aedelas-blackmoore}Blackmoore{/link}, {link:thrall}Thrall{/link} aprendeu o que era a crueldade. Com Taretha, aprendeu que os humanos podiam ser bons. A memória dela é uma das razões pelas quais o Chefe Guerreiro da {link:horde}Horda{/link} nunca odiou toda a humanidade.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ainda criança, percebeu que o bebê {link:orcs}orc{/link} não conseguia comer a carne que lhe davam, e assim salvou sua vida. Sua mãe o amamentou.
• Escondia bilhetes dentro dos livros que levava à cela de {link:thrall}Thrall{/link}, e os dois se corresponderam por anos.
• Quando Thrall fugiu do {link:durnholde-keep}Desterro{/link}, ela ateou um fogo como distração e deixou-lhe um manto para passar pelo portão. Não quis ir com ele, por medo do que {link:aedelas-blackmoore}Blackmoore{/link} faria à sua família.
• Encontrou Thrall em segredo na noite anterior à chegada de seu exército ao Desterro. Blackmoore mandou segui-la, e mandou matá-la.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhum registro diz como o pingente de Taretha foi parar nas mãos dos senhores de {link:alterac-mountains}Alterac{/link}, nem onde Taretha repousa.]=],
		},
	},
	chapters = {
		{
			title = "O Presente de Taretha",
			hint = "Recupere o pingente que o Chefe Guerreiro deseja.",
			text = [=[Muito depois de sua morte, orcs enviados por {link:thrall}Thrall{/link} vieram a {link:hillsbrad-foothills}Eira dos Montes{/link} atrás de um único pingente que fora dela. Encontraram-no no pescoço de {link:elysa}Elysa{/link}, a amante de {link:lord-aliden-perenolde}Aliden Perenolde{/link}. Ela o entregou de bom grado. O {link:orcs}orc{/link} que o recebeu não conseguia entender por que o Chefe Guerreiro gastaria tanto por uma coisa tão pequena.]=],
		},
	},
	mentions = {
		{ text = "O Legado de {link:aedelas-blackmoore}Blackmoore{/link}" },
		{ text = "{link:lord-aliden-perenolde}Lorde Aliden Perenolde{/link}" },
		{ text = "O Presente de Taretha" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu amigo, a quem chamava de irmão" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "seu senhor e seu assassino" },
		{ id = "krusk", name = "Krusk", note = "recuperou seu pingente para o Chefe Guerreiro" },
	},
})

