Translate("ptBR", "battle-of-hillsbrad", {
	title = "Batalha de Eira dos Montes",
	sections = {
		{
			title = "Resumo",
			text = [=[A Batalha de Eira dos Montes é a guerra que os {link:forsaken}Renegados{/link} da {link:tarren-mill}Serraria Tarren{/link} travam agora contra os humanos do contraforte. Seu objetivo é claro: quebrar os humanos de {link:hillsbrad-foothills}Eira dos Montes{/link} até que os boticários terminem a nova praga, e então arrasar {link:southshore}Costa Sul{/link}.]=],
		},
		{
			title = "A Campanha",
			text = [=[A ordem veio de {link:varimathras}Varimathras{/link} para a {link:high-executor-darthalia}Alta Executora Darthalia{/link}. Quando sua batedora na {link:southpoint-tower}Torre do Sul{/link} avisou que a cidade estava madura, o ataque começou em etapas.

• {b}As fazendas.{/b} A Guarda da Morte atacou primeiro as fazendas do norte e seus donos, para cortar a comida de {link:hillsbrad-foothills}Eira dos Montes{/link}.
• {b}Os pomares.{/b} Os camponeses que fugiram para os pomares do sul foram caçados ali.
• {b}A ferraria.{/b} O ferreiro e seus aprendizes foram mortos, e o ferro da cidade foi levado.
• {b}O conselho.{/b} O magistrado e o conselho foram marcados para morrer, a carta da cidade para ser queimada, e seu registro para ser roubado.
• {b}A mina.{/b} O capataz e os mineiros da {link:azurelode-mine}Mina Veioazul{/link} foram atacados, para que {link:sylvanas-windrunner}a Dama Sombria{/link} pudesse armar seus soldados com ela.
• {b}{link:dun-garok}Dun Garok{/link}.{/b} Por último veio o cerco à fortaleza anã na {link:thoradin-s-wall}Muralha de Thoradin{/link}.]=],
		},
		{
			title = "O Outro Lado",
			text = [=[Os humanos não morrem calados. Moradores de {link:hillsbrad-foothills}Eira dos Montes{/link} mataram guardas, boticários e Sicários {link:forsaken}Renegados{/link}, e emboscaram os suprimentos enviados da {link:undercity}Cidade Baixa{/link}. {link:high-executor-darthalia}Darthalia{/link} mantém seus nomes numa lista de recompensas.]=],
		},
		{
			title = "Os Boticários",
			text = [=[Enquanto os soldados lutam, o {link:apothecary-lydon}Boticário Lydon{/link} testa seus elixires nos cães e nos fazendeiros capturados de {link:hillsbrad-foothills}Eira dos Montes{/link}. Cada um deles é um passo rumo à praga que {link:sylvanas-windrunner}a Dama Sombria{/link} ordenou.]=],
		},
	},
})

Translate("ptBR", "internment-camps", {
	title = "Campos de Internação",
	aliases = { "campo de internação", "campos de internação" },
	sections = {
		{
			title = "Resumo",
			text = [=[Depois da {link:second-war}Segunda Guerra{/link}, os orcs que sobreviveram não foram passados a fio de espada. Foram reunidos em campos de internação por toda {link:lordaeron}Lordaeron{/link}, vigiados pelos soldados da {link:alliance}Aliança{/link}. Os campos deviam ser um lugar para manter um inimigo derrotado. Tornaram-se algo pior.]=],
		},
		{
			title = "A Letargia",
			text = [=[Isolados do poder demoníaco que os impelira, os orcs nos campos ficaram apáticos e doentes de espírito. Muitos simplesmente se sentavam atrás das muralhas e não tentavam sair. Os humanos que os vigiavam não conseguiam entender isso. Alguns tinham pena deles. Outros lucravam com eles.]=],
		},
		{
			title = "O Desterro",
			text = [=[Os campos eram governados a partir do {link:durnholde-keep}Forte do Desterro{/link}, em {link:hillsbrad-foothills}Eira dos Montes{/link}, sob o Tenente-general {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. Blackmoore via mais que prisioneiros atrás de suas muralhas. Via um exército que poderia ser seu, se um {link:orcs}orc{/link} criado por ele mesmo o liderasse.]=],
		},
		{
			title = "A Libertação",
			text = [=[Esse {link:orcs}orc{/link} era {link:thrall}Thrall{/link}. Ele fugiu do {link:durnholde-keep}Desterro{/link}, encontrou os clãs livres e aprendeu os caminhos do xamã. Com {link:orgrim-doomhammer}Orgrim Doomhammer{/link} a seu lado, atacou os campos um a um e libertou os orcs lá dentro. Doomhammer tombou numa dessas batalhas. Por fim, Thrall chegou ao próprio Desterro, e os campos chegaram ao fim.]=],
		},
	},
})
